def _pp_plan_modules_for_file(file_path: Path) -> set[str] | None:
    """Return the set of PP-managed submodule names for ``file_path``'s model directory.

    Returns ``None`` when the PP plan mapping is unpopulated/empty, or when the model
    directory has no entry. In those cases TRF011 produces zero violations for the file.
    """
    if not _PP_PLAN_MODULES_BY_MODEL_DIR:
        return None
    model_dir = _model_dir_name(file_path)
    if model_dir is None:
        return None
    return _PP_PLAN_MODULES_BY_MODEL_DIR.get(model_dir)


def _pp_module_self_reference(iter_node: ast.AST, pp_modules: set[str]) -> str | None:
    """If ``iter_node`` iterates a PP-managed ``self.<module>``, return that self-reference.

    Unwraps common iteration wrappers such as ``enumerate(...)`` and ``reversed(...)``.
    """
    if (
        isinstance(iter_node, ast.Call)
        and isinstance(iter_node.func, ast.Name)
        and iter_node.func.id in {"enumerate", "reversed", "list", "tuple", "iter"}
        and iter_node.args
    ):
        return _pp_module_self_reference(iter_node.args[0], pp_modules)
    if (
        isinstance(iter_node, ast.Attribute)
        and isinstance(iter_node.value, ast.Name)
        and iter_node.value.id == "self"
        and iter_node.attr in pp_modules
    ):
        return full_name(iter_node)
    return None


def _collect_pp_loop_vars(function_node: ast.FunctionDef, pp_modules: set[str]) -> dict[str, str]:
    """Map each loop variable iterating a PP-managed submodule to that module's self-reference.

    Handles ``for x in self.layers:`` (and wrappers like ``reversed(self.layers)``) as well as
    ``for i, x in enumerate(self.layers):``.
    """
    loop_vars: dict[str, str] = {}
    for sub_node in ast.walk(function_node):
        if not isinstance(sub_node, (ast.For, ast.AsyncFor)):
            continue
        self_ref = _pp_module_self_reference(sub_node.iter, pp_modules)
        if self_ref is None:
            continue
        target = sub_node.target
        is_enumerate = (
            isinstance(sub_node.iter, ast.Call)
            and isinstance(sub_node.iter.func, ast.Name)
            and sub_node.iter.func.id == "enumerate"
        )
        if isinstance(target, ast.Name):
            loop_vars[target.id] = self_ref
        elif (
            is_enumerate
            and isinstance(target, ast.Tuple)
            and len(target.elts) == 2
            and isinstance(target.elts[1], ast.Name)
        ):
            loop_vars[target.elts[1].id] = self_ref
    return loop_vars


def trf011_check_pp_plan_attribute_safety(
    tree: ast.Module, file_path: Path, source_lines: list[str], violations: list[Violation], rule_id: str
) -> list[Violation]:
    """Flag unsafe attribute accesses on submodules managed by the pipeline parallelism plan.

    Reaching into a PP-managed submodule (or an element iterated from one) for a non-standard
    ``nn.Module`` attribute is unsafe: pipeline parallelism may place that submodule on another
    device, so directly touching its internals from ``forward`` can break under PP.
    """
    pp_modules = _pp_plan_modules_for_file(file_path)
    if not pp_modules:
        return violations

    class_to_bases = _collect_class_bases(tree)
    for node in tree.body:
        if not isinstance(node, ast.ClassDef):
            continue
        if not _inherits_pretrained_model(node.name, class_to_bases):
            continue

        forward_method = _class_methods(node).get("forward")
        if forward_method is None:
            continue

        pp_loop_vars = _collect_pp_loop_vars(forward_method, pp_modules)

        for sub_node in ast.walk(forward_method):
            if not isinstance(sub_node, ast.Attribute):
                continue

            # Case 1: attribute access on a loop variable iterating a PP-managed submodule.
            if isinstance(sub_node.value, ast.Name) and sub_node.value.id in pp_loop_vars:
                if _is_standard_nn_module_attr(sub_node.attr):
                    continue
                if _has_rule_suppression(source_lines, rule_id, sub_node.lineno):
                    continue
                access_expr = full_name(sub_node)
                self_ref = pp_loop_vars[sub_node.value.id]
                violations.append(
                    Violation(
                        file_path=file_path,
                        line_number=sub_node.lineno,
                        rule_id=rule_id,
                        message=(
                            f"{rule_id}: unsafe attribute access `{access_expr}` on submodule `{self_ref}` "
                            "managed by the pipeline parallelism plan."
                        ),
                    )
                )
                continue

            # Case 2: direct attribute access of the form `self.<pp_module>.<attr>`.
            value = sub_node.value
            if (
                isinstance(value, ast.Attribute)
                and isinstance(value.value, ast.Name)
                and value.value.id == "self"
                and value.attr in pp_modules
            ):
                if _is_standard_nn_module_attr(sub_node.attr):
                    continue
                if _has_rule_suppression(source_lines, rule_id, sub_node.lineno):
                    continue
                access_chain = full_name(sub_node)
                violations.append(
                    Violation(
                        file_path=file_path,
                        line_number=sub_node.lineno,
                        rule_id=rule_id,
                        message=(
                            f"{rule_id}: unsafe attribute access `{access_chain}` on a submodule "
                            "managed by the pipeline parallelism plan."
                        ),
                    )
                )

    return violations


